def round_half(x: float) -> int:
    # For positive numbers, when fractional part is exactly 0.5, round towards even
    # Since 8.5 should round to 8 (even), we implement round half to even
    if x >= 0:
        # For non-negative numbers
        fractional = x - int(x)
        if fractional < 0.5:
            return int(x)
        elif fractional > 0.5:
            return int(x) + 1
        else:  # fractional == 0.5
            # Round to nearest even integer
            if int(x) % 2 == 0:
                return int(x)
            else:
                return int(x) + 1
    else:
        # For negative numbers, similar logic
        fractional = x - int(x)
        # Adjust for negative number fractional parts
        if fractional > -0.5:
            return int(x)
        elif fractional < -0.5:
            return int(x) - 1
        else:  # fractional == -0.5
            # Round to nearest even integer
            if int(x) % 2 == 0:
                return int(x)
            else:
                return int(x) - 1

